function renderPageHeader(){const isCompany=state.user?.role==='company';const labels={overview:isCompany?'navCompany':'navOverview',map:'navMap',activity:'navActivity',areas:isCompany?'navCompanyAreas':'navAreas',guide:'navGuide',details:'navDetails'};elText('breadcrumb',tr(labels[state.page]));const heading={overview:isCompany?(state.lang==='ar'?'لوحة مراقبة أعمالك':'Company Observation Workspace'):tr('overviewTitle'),map:tr('mapExplorer'),activity:tr('navActivity'),areas:tr(labels.areas),guide:tr('navGuide'),details:tr('navDetails')};elText('pageHeading',heading[state.page]);const sub={overview:isCompany?((state.user.company_name||tr('company'))+' · '+tr('overviewDesc')):tr('overviewDesc'),map:tr('mapDisclaimer'),activity:tr('dailySubtitle'),areas:tr('areasSubtitle'),guide:tr('guide3'),details:tr('aboutText')};elText('pageSubheading',sub[state.page]);}
function renderAccountButton(){$('companyQuick').classList.toggle('hidden',state.user?.role!=='company');if(state.user?.role==='company')renderCompanyQuick();elText('accountButton',state.user?tr('signOut'):tr('signIn'));elText('avatar',state.user?(state.user.full_name||'U').slice(0,2).toUpperCase():'EF');elText('roleBadge',state.user?tr(state.user.role):tr('previewPublic'));const company=state.user?.role==='company';elText('areasTitle',tr(company?'companyAreas':'myAreas'));$('categoryField').classList.toggle('hidden',!company);}
function renderNav(){const role=state.user?.role==='company'?'company':'individual';$('nav').innerHTML='';for(const [page,icon,key] of NAV[role]){const b=document.createElement('button');b.className=state.page===page?'active':'';b.dataset.page=page;b.innerHTML=`<span class="nav-icon">${icon}</span><span>${esc(tr(key))}</span>`;$('nav').appendChild(b);}}
function navigate(page){if(page==='guide'&&state.user?.role==='company')page='details';if(!$(page+'Page'))return;stopTimeline();state.page=page;document.querySelectorAll('.page').forEach(el=>el.classList.toggle('active',el.id===page+'Page'));renderPageHeader();renderNav();if(page==='overview'||page==='map')mountMap(page);if(page==='activity')renderAnalytics();if(page==='overview')renderOverviewCharts();if(page==='areas')loadAreas();setTimeout(()=>Object.values(state.chartInstances).forEach(x=>x.resize()),60);window.scrollTo({top:0,behavior:'smooth'});}
function renderRegionOptions(){const n=$('regionFilter');if(!n)return;const old=state.filters.region;n.innerHTML=`<option value="">${esc(tr('allRegions'))}</option>`;for(const region of Object.keys(state.meta?.regions||{})){const o=document.createElement('option');o.value=region;o.textContent=regionName(region);n.appendChild(o)}n.value=old;}
function renderCountryOptions(){const n=$('countryFilter');if(!n)return;const old=state.filters.country;const regions=state.meta?.regions||{};const countries=state.filters.region?(regions[state.filters.region]||[]):[];n.disabled=!state.filters.region;n.innerHTML=`<option value="">${esc(state.filters.region?tr('allCountries'):tr('selectRegionFirst'))}</option>`;for(const name of countries){const o=document.createElement('option');o.value=name;o.textContent=areaName(name);n.appendChild(o)}if(!countries.includes(old)){state.filters.country='';}n.value=state.filters.country;}
function renderAreaCountryOptions(){const n=$('areaCountry');if(!n)return;const old=n.value;const regions=state.meta?.regions||{};const countries=[...new Set(Object.values(regions).flat())].sort();n.innerHTML='';for(const name of countries){const o=document.createElement('option');o.value=name;o.textContent=areaName(name);n.appendChild(o)}n.value=(countries.includes(old)?old:countries.includes(state.filters.country)?state.filters.country:countries[0])||'';}
function renderMetaText(){if(!state.meta)return;const m=state.meta.dataset;elText('freshness',`${tr('dataThrough')} ${state.meta.max_date}`);elText('windowContext',`${tr('period')}: ${state.filters.start||state.meta.min_date} — ${state.filters.end||state.meta.max_date} · ${tr('sourceClipped')}: ${pretty(m.outside_africa_rows)}`);elText('methodData',`${pretty(m.imported_rows)} ${tr('datasetCount')} · ${pretty(m.africa_rows)} ${tr('windowRange')} · ${pretty(m.outside_africa_rows)} ${tr('sourceClipped')}`);}
function syncFilterInputs(){for(const id of ['region','country','instrument','confidence','daynight']){$(id+'Filter').value=state.filters[id]}$('fromFilter').value=state.filters.start;$('toFilter').value=state.filters.end;}
async function refresh(){if(!state.meta)return;const requestId=++state.requestId;state.loading=true;elText('loadIndicator',tr('loading'));const query=urlParams();try{const [dash,heat]=await Promise.all([api('/api/dashboard?'+query),api('/api/hotspots?'+query)]);if(requestId!==state.requestId)return;state.dashboard=dash;state.hotspots=heat;renderDashboard();renderMapCells();renderMetaText();}catch(err){if(requestId===state.requestId)toast(err.message||tr('error'));}finally{if(requestId===state.requestId){state.loading=false;elText('loadIndicator','')}}}
function statsHTML(){const s=state.dashboard.summary;const items=[['♨','detectionCount',pretty(s.detections),'nonUnique'],['⌖','countriesObserved',pretty(s.countries),'inWindow'],['✓','highConfidence',pretty(s.high_confidence),'normalized'],['✳','maximumFRP',pretty(s.max_frp,1)+' MW','inWindow']];return items.map(([ic,label,val,foot])=>`<article class="stat"><span class="stat-icon">${ic}</span><div class="stat-label">${esc(tr(label))}</div><div class="stat-value">${esc(val)}</div><div class="stat-foot">${esc(tr(foot))}</div></article>`).join('')}
function renderDashboard(){if(!state.dashboard)return;const d=state.dashboard;$('stats').innerHTML=statsHTML();$('analyticsStats').innerHTML=statsHTML();const sensors=d.sensors.map(s=>`<div class="metric-line"><span>${esc(s.instrument)} ${esc(tr('instrumentMean'))}</span><b>${pretty(s.mean_frp,2)} MW</b></div>`).join('');$('activityContext').innerHTML=`<div class="metric-line"><span>${esc(tr('selectedDays'))}</span><b>${pretty(d.summary.days)}</b></div>${sensors}`;const max=Math.max(1,...d.countries.map(x=>x.count));$('countriesList').innerHTML=d.countries.length?d.countries.slice(0,7).map(x=>`<div class="rank-row"><div class="rank-header"><span>${esc(areaName(x.country))}</span><b>${pretty(x.count)}</b></div><div class="rank-bar"><span style="width:${Math.max(2,x.count/max*100)}%"></span></div></div>`).join(''):`<div class="empty">${esc(tr('noneFound'))}</div>`;
$('recentRows').innerHTML=d.recent.length?d.recent.map(x=>`<tr><td>${esc(x.date)} ${esc(x.time||'')} UTC</td><td>${esc(areaName(x.country))}</td><td>${esc(x.instrument)}</td><td><span class="tag ${x.confidence==='High'?'high':''}">${esc(x.confidence==='High'?tr('high'):tr('nominal'))}</span></td><td>${pretty(x.frp,2)}</td><td>${Number(x.lat).toFixed(3)}, ${Number(x.lon).toFixed(3)}</td></tr>`).join(''):`<tr><td colspan="6">${esc(tr('noneFound'))}</td></tr>`;
$('topDetections').innerHTML=d.top.length?d.top.slice(0,8).map(x=>`<div class="top-item"><div><b>${esc(areaName(x.country))}</b><small>${esc(x.date)} · ${esc(x.instrument)} · ${Number(x.lat).toFixed(2)}, ${Number(x.lon).toFixed(2)}</small></div><strong>${pretty(x.frp,1)} MW</strong></div>`).join(''):`<div class="empty">${tr('noneFound')}</div>`;
if(state.page==='overview')renderOverviewCharts();if(state.page==='activity')renderAnalytics();}
/* Dependency-free chart fallback: all data remains visualized if ECharts CDN is unavailable. */
function fallbackChart(id,option){
 const el=$(id);if(!el)return;
 const width=700,height=280,arr=option.series?.[0]?.data||[];
 const raw=arr.map(x=>typeof x==='object'?Number(x.value||0):Number(x||0));
 const max=Math.max(1,...raw);
 const labels=(option.xAxis?.type==='category'?option.xAxis?.data:option.yAxis?.type==='category'?option.yAxis?.data:arr.map(x=>x.name))||[];
 const isPie=option.series?.[0]?.type==='pie';const isLine=option.series?.[0]?.type==='line';
 const isHorizontal=option.yAxis?.type==='category';
 let markup=`<svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMidYMid meet" style="width:100%;height:100%;font:11px Inter,Cairo,sans-serif" aria-label="${esc(tr('dailyActivity'))}">`;
 if(!arr.length){el.innerHTML=`<div class="empty">${tr('noneFound')}</div>`;return;}
 if(isPie){
   const sum=raw.reduce((a,b)=>a+b,0)||1;
   let progress=0;const cx=270,cy=120,r=84;
   const colors=['#64a47c','#ec9862','#85adca','#d8b96d','#bd6c6e'];
   for(let i=0;i<raw.length;i++){
     const frac=raw[i]/sum,a0=progress*Math.PI*2-Math.PI/2,a1=(progress+frac)*Math.PI*2-Math.PI/2;
     progress+=frac;
     if(frac===0)continue;
     if(frac>.9999){markup+=`<circle cx="${cx}" cy="${cy}" r="${r}" fill="${colors[i%colors.length]}"><title>${esc(labels[i]||arr[i].name)}: ${pretty(raw[i])}</title></circle>`;continue;}
     const x0=cx+r*Math.cos(a0),y0=cy+r*Math.sin(a0),x1=cx+r*Math.cos(a1),y1=cy+r*Math.sin(a1),big=frac>.5?1:0;
     markup+=`<path d="M${cx} ${cy} L${x0} ${y0} A${r} ${r} 0 ${big} 1 ${x1} ${y1} Z" fill="${colors[i%colors.length]}"><title>${esc(labels[i]||arr[i].name)}: ${pretty(raw[i])}</title></path>`;
   }
   markup+=`<circle cx="${cx}" cy="${cy}" r="51" fill="white"/><text x="${cx}" y="${cy+5}" font-size="16" font-weight="800" fill="#2d6041" text-anchor="middle">${esc(pretty(sum))}</text>`;
   for(let i=0;i<raw.length;i++){
      markup+=`<rect x="420" y="${50+i*32}" width="10" height="10" rx="2" fill="${colors[i%colors.length]}"/><text x="436" y="${60+i*32}" font-size="11" fill="#526d59">${esc(labels[i]||arr[i].name||'')} ${esc(pretty(raw[i]))}</text>`;
   }
 }else if(isHorizontal){
   const left=170,right=35,usable=width-left-right;
   for(let i=0;i<raw.length;i++){
      const row=34+i*Math.min(40,210/Math.max(1,raw.length)),h=18,w=Math.max(.5,raw[i]/max*usable);
      markup+=`<text x="${left-10}" y="${row+13}" font-size="10" text-anchor="end" fill="#69836e">${esc(String(labels[i]||''))}</text><rect x="${left}" y="${row}" width="${usable}" height="${h}" rx="4" fill="#eff4ef"/><rect x="${left}" y="${row}" width="${w}" height="${h}" rx="4" fill="#69a680"><title>${esc(pretty(raw[i]))}</title></rect><text x="${left+Math.min(w+5,usable-10)}" y="${row+13}" font-size="10" fill="#325b3d">${esc(pretty(raw[i]))}</text>`;
   }
 }else{
   const left=65,right=20,top=25,bottom=55,w=width-left-right,h=height-top-bottom;
   for(let i=0;i<=4;i++){const y=top+i*h/4;markup+=`<path d="M${left} ${y} H${width-right}" stroke="#edf3eb"/><text x="${left-8}" y="${y+4}" font-size="9" text-anchor="end" fill="#8da28c">${esc(pretty(max*(4-i)/4))}</text>`;}
   if(isLine){
      const xy=raw.map((v,i)=>[left+i*w/Math.max(1,raw.length-1),top+h-v/max*h]);
      markup+=`<path d="${xy.map((p,i)=>`${i?'L':'M'}${p[0]} ${p[1]}`).join(' ')}" fill="none" stroke="#53946b" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`;
      for(let i=0;i<xy.length;i++)markup+=`<circle cx="${xy[i][0]}" cy="${xy[i][1]}" r="4" fill="#53946b"><title>${esc(labels[i]||'')}: ${pretty(raw[i])}</title></circle>`;
   }else{
      const step=w/Math.max(1,raw.length),bw=Math.min(48,step*.65);
      for(let i=0;i<raw.length;i++){const x=left+i*step+step/2-bw/2,barh=h*raw[i]/max;markup+=`<rect x="${x}" y="${top+h-barh}" width="${bw}" height="${Math.max(1,barh)}" rx="3" fill="#77aa86"><title>${esc(labels[i]||'')}: ${pretty(raw[i])}</title></rect>`;}
   }
   for(let i=0;i<labels.length;i++){const x=left+(isLine?i*w/Math.max(1,labels.length-1):(i+.5)*w/labels.length);markup+=`<text x="${x}" y="${top+h+20}" font-size="9" text-anchor="middle" fill="#91a292">${esc(String(labels[i]||'').slice(0,11))}</text>`;}
 }
 markup+='</svg>';el.innerHTML=markup;
}

/* Geographic fallback uses the bundled real country geometry & real detections.
   It works locally without remote map libraries/tiles, but lacks interactive panning. */
function renderFallbackMap(){
 if(!state.geo||!state.hotspots)return;
 const container=$('sharedMap'), width=1000,height=510;
 container.style.display='block';
 const inRegion=state.filters.region?state.meta.regions[state.filters.region]:null;
 const names=state.filters.country?[state.filters.country]:inRegion;
 const features=state.geo.features.filter(f=>!names||names.includes(f.properties.name));
 if(!features.length)return;
 const geometries=features.flatMap(f=>{
   const g=f.geometry;
   const polygons=g.type==='Polygon'?[g.coordinates]:g.coordinates;
   return polygons.flatMap(p=>p);
 });
 let xs=[],ys=[];
 for(const ring of geometries)for(const [lon,lat] of ring){xs.push(lon);ys.push(lat)}
 const xMin=Math.min(...xs),xMax=Math.max(...xs),yMin=Math.min(...ys),yMax=Math.max(...ys);
 let lon0=xMin,lon1=xMax,lat0=yMin,lat1=yMax;
 let dx=Math.max(2,lon1-lon0)*1.16,dy=Math.max(2,lat1-lat0)*1.16;
 const ratio=width/height;
 if(dx/dy<ratio)dx=dy*ratio;else dy=dx/ratio;
 const centerX=(lon1+lon0)/2,centerY=(lat1+lat0)/2;
 lon0=centerX-dx/2;lon1=centerX+dx/2;lat0=centerY-dy/2;lat1=centerY+dy/2;
 const toX=lon=>(lon-lon0)/(lon1-lon0)*width;
 const toY=lat=>(lat1-lat)/(lat1-lat0)*height;
 let svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" style="width:100%;height:100%;background:#e7f0eb;border-radius:12px" role="img" aria-label="Geographic fire observation heatmap"><defs><pattern id="geo-grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M 40 0 L 0 0 0 40" fill="none" stroke="#cee2d2" stroke-width="1"/></pattern></defs><rect width="${width}" height="${height}" fill="url(#geo-grid)"/>`;
 for(const ring of geometries){
   if(ring.length<3)continue;
   const coords=ring.map(([lon,lat],i)=>(i?'L':'M')+toX(lon).toFixed(1)+' '+toY(lat).toFixed(1)).join(' ');
   svg+=`<path d="${coords}Z" fill="#afcbb2" fill-opacity=".7" stroke="#759e84" stroke-width="1"/>`;
 }
 const max=Math.max(1,...state.hotspots.cells.map(c=>c.count));
 for(const c of state.hotspots.cells){
    const x=toX(c.lon),y=toY(c.lat);if(x<0||x>width||y<0||y>height)continue;
    const share=Math.sqrt(c.count/max),r=(state.mapMode==='heat'?6:3)+share*(state.mapMode==='heat'?15:9);
    const color=share>.7?'#cb583c':share>.4?'#ee9752':share>.22?'#d9c263':'#72aa7c';
    svg+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r.toFixed(1)}" fill="${color}" fill-opacity="${state.mapMode==='heat'?.32:.8}" stroke="${state.mapMode==='heat'?'none':'#fff'}"><title>${pretty(c.count)} ${esc(tr('count'))} · Max FRP ${pretty(c.max_frp,1)} MW</title></circle>`;
 }
 svg+='</svg>';container.innerHTML=svg;
 container.onclick=e=>{
   if(!state.filters.country){toast(tr('chooseCountry'));return;}
   const rect=e.currentTarget.querySelector('svg').getBoundingClientRect();
   const x=(e.clientX-rect.left)/rect.width*width,y=(e.clientY-rect.top)/rect.height*height;
   const lat=lat1-y/height*(lat1-lat0),lon=lon0+x/width*(lon1-lon0);
   $('areaLat').value=lat.toFixed(5);$('areaLon').value=lon.toFixed(5);$('areaCountry').value=state.filters.country;
   if(!state.user)openAuth();else{navigate('areas');toast(tr('coordinateSet'));}
 };
 elText('mapCellContext',`${pretty(state.hotspots.returned)} / ${pretty(state.hotspots.total_cells)} ${tr('observationCells')}`);
}

function chart(id,option){if(!window.echarts){fallbackChart(id,option);return;}const el=$(id);if(!el||el.clientWidth===0)return;let instance=state.chartInstances[id];if(!instance){instance=echarts.init(el);state.chartInstances[id]=instance;}instance.setOption(option,true);instance.resize();}
const palette=['#65a37c','#ee9a62','#89aeca','#d4b36b','#ca6b58','#a89cb7'];
const common={animationDuration:380,textStyle:{fontFamily:state.lang==='ar'?'Cairo':'Inter',fontSize:11},tooltip:{trigger:'axis',backgroundColor:'#fff',borderColor:'#e3ece0',textStyle:{fontSize:11,color:'#214732'}},grid:{left:52,right:20,top:30,bottom:36},xAxis:{axisLine:{lineStyle:{color:'#e6ede1'}},axisLabel:{color:'#819583',fontSize:10}},yAxis:{splitLine:{lineStyle:{color:'#eef3ec'}},axisLabel:{color:'#8b9c8e',fontSize:10}}};
function renderOverviewCharts(){if(!state.dashboard)return;const d=state.dashboard;const series=d.daily.map(x=>x.count);chart('dailyChart',{...common,xAxis:{...common.xAxis,type:'category',data:d.daily.map(x=>x.date.slice(5)),boundaryGap:false},yAxis:{...common.yAxis,type:'value'},series:[{name:tr('count'),type:'line',data:series,smooth:true,symbol:'circle',symbolSize:6,lineStyle:{color:'#508a65',width:3},itemStyle:{color:'#508a65'},areaStyle:{color:'rgba(81,139,96,.15)'}}]});chart('sensorChart',{textStyle:common.textStyle,tooltip:{trigger:'item'},legend:{bottom:0,textStyle:{color:'#64836c',fontSize:10}},color:palette,series:[{type:'pie',radius:['56%','78%'],center:['50%','44%'],label:{show:false},data:d.sensors.map(x=>({name:x.instrument,value:x.count}))}]});}
function renderAnalytics(){const d=state.dashboard;if(!d)return;
const bar=(id,arr,namer,vertical=false)=>chart(id,{...common,color:palette,tooltip:{trigger:'axis'},grid:{left:vertical?110:52,right:20,top:25,bottom:vertical?30:50},xAxis:vertical?{type:'value',axisLabel:common.xAxis.axisLabel}:{type:'category',data:arr.map(namer),axisLabel:{rotate:arr.length>4?25:0,fontSize:10,color:'#8b9c8e'}},yAxis:vertical?{type:'category',data:arr.map(namer),axisLabel:{color:'#8b9c8e',fontSize:10}}:{type:'value',splitLine:common.yAxis.splitLine,axisLabel:common.yAxis.axisLabel},series:[{type:'bar',data:arr.map(x=>x.count),barMaxWidth:32,itemStyle:{color:'#64a47c',borderRadius:vertical?[0,5,5,0]:[5,5,0,0]}}]});
bar('instrumentBars',d.sensors,x=>x.instrument);
chart('dayNightChart',{textStyle:common.textStyle,tooltip:{trigger:'item'},legend:{bottom:5},color:['#e4a75a','#6888af'],series:[{type:'pie',radius:['40%','72%'],data:d.daynight.map(x=>({name:tr(x.daynight.toLowerCase()),value:x.count}))}]});
bar('regionChart',d.regions,x=>regionName(x.region),true);
chart('hoursChart',{...common,xAxis:{type:'category',data:d.hours.map(x=>x.hour||'00'),axisLabel:common.xAxis.axisLabel},yAxis:{type:'value',splitLine:common.yAxis.splitLine},series:[{type:'bar',data:d.hours.map(x=>x.count),itemStyle:{color:'#81a9c6',borderRadius:[3,3,0,0]}}]});
chart('confidenceChart',{tooltip:{trigger:'item'},legend:{bottom:5},color:['#66a47d','#eca365'],textStyle:common.textStyle,series:[{type:'pie',radius:['45%','70%'],data:d.confidence.map(x=>({name:x.confidence==='High'?tr('high'):tr('nominal'),value:x.count}))}]});
bar('frpChart',d.frp_bands,x=>String(x.severity||'').split(' (')[0]);}
function createMap(){if(state.map||!window.L)return;const mapEl=$('sharedMap');mapEl.style.display='block';state.map=L.map(mapEl,{center:[3,19],zoom:3,minZoom:2,preferCanvas:true,scrollWheelZoom:false,zoomControl:true});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors',maxZoom:18}).addTo(state.map);state.map.on('click',event=>{if(!state.filters.country){toast(tr('chooseCountry'));return;}const pos=event.latlng;$('areaLat').value=pos.lat.toFixed(5);$('areaLon').value=pos.lng.toFixed(5);$('areaCountry').value=state.filters.country;if(!state.user){toast(tr('loginRequired'));openAuth();return;}navigate('areas');toast(tr('coordinateSet'));});}
function mountMap(page){createMap();const mount=$(page==='map'?'exploreMapMount':'overviewMapMount');mount.appendChild($('sharedMap'));$('sharedMap').style.display='block';if(!state.map){renderFallbackMap();return;}setTimeout(()=>{state.map.invalidateSize(true);focusMap();},100);renderMapCells();}
function focusMap(){if(!state.map||!state.geo||!state.meta)return;const newKey=state.filters.region+'|'+state.filters.country;if(state.prevGeoKey===newKey)return;state.prevGeoKey=newKey;if(state.mapOutline)state.map.removeLayer(state.mapOutline);const countries=state.filters.country?[state.filters.country]:state.filters.region?state.meta.regions[state.filters.region]:null;const feats=state.geo.features.filter(f=>countries===null||countries?.includes(f.properties.name));state.mapOutline=L.geoJSON({type:'FeatureCollection',features:feats},{style:{color:'#559578',fillColor:'#61a27a',weight:1.1,fillOpacity:.025,opacity:.6}}).addTo(state.map);if(state.filters.country||state.filters.region){const bounds=state.mapOutline.getBounds();if(bounds.isValid())state.map.fitBounds(bounds.pad(.12),{animate:false});}else state.map.setView([2.0,20],3,{animate:false});}
function renderMapCells(){if(!state.hotspots)return;if(!state.map){renderFallbackMap();return;}const h=state.hotspots;if(state.mapOverlay){state.map.removeLayer(state.mapOverlay);state.mapOverlay=null;}const max=Math.max(1,...h.cells.map(x=>x.count));if(state.mapMode==='heat'&&L.heatLayer){const heat=h.cells.map(c=>[c.lat,c.lon,Math.min(1,.1+.9*Math.sqrt(c.count/max))]);state.mapOverlay=L.heatLayer(heat,{radius:19,blur:22,maxZoom:9,max:1,minOpacity:.18,gradient:{.15:'#60b789',.4:'#b2c65d',.7:'#f5a44c',1:'#cf553c'}}).addTo(state.map);}else{const layer=L.layerGroup();for(const c of h.cells.slice(0,1700)){const intensity=Math.min(1,c.count/max);L.circleMarker([c.lat,c.lon],{radius:3+7*Math.sqrt(intensity),weight:1,color:'#faf7e4',fillColor:intensity>.48?'#d36142':intensity>.12?'#eaa14d':'#6da784',fillOpacity:.85}).bindPopup(`<b>${pretty(c.count)} ${esc(tr('count'))}</b><br>Max FRP: ${pretty(c.max_frp,1)} MW<br>${c.lat.toFixed(2)}, ${c.lon.toFixed(2)}`).addTo(layer);}state.mapOverlay=layer.addTo(state.map);}elText('mapCellContext',`${pretty(h.returned)} / ${pretty(h.total_cells)} ${tr('observationCells')} · ${h.truncated?tr('cellsTruncated'):tr('allCells')}`);focusMap();}
function stopTimeline(){if(state.timelineTimer){clearInterval(state.timelineTimer);state.timelineTimer=null;}elText('playButton',`▶ ${tr('play')}`);}
function datesBetween(first,last){if(!first||!last)return[];const list=[];let t=Date.parse(first+'T00:00:00Z');const end=Date.parse(last+'T00:00:00Z');while(t<=end&&list.length<366){list.push(new Date(t).toISOString().slice(0,10));t+=86400000;}return list;}
function renderTimeline(){const dates=datesBetween(state.meta?.min_date,state.meta?.max_date);state.dates=dates;const slider=$('timelineRange');slider.max=Math.max(0,dates.length-1);slider.value=state.filters.start===state.filters.end&&dates.includes(state.filters.start)?dates.indexOf(state.filters.start):dates.length-1;elText('timelineFirst',dates[0]||'—');elText('timelineLast',dates.at(-1)||'—');elText('timelineCurrent',state.filters.start===state.filters.end&&state.filters.start?state.filters.start:(state.lang==='ar'?'كل الأيام':'All dates'));}
function timelineSelect(index){const date=state.dates[Number(index)];if(!date)return;state.filters.start=date;state.filters.end=date;syncFilterInputs();elText('timelineCurrent',date);refresh();}
function playTimeline(){if(state.timelineTimer){stopTimeline();return;}const dates=state.dates||[];if(!dates.length)return;let i=state.filters.start===state.filters.end?Math.max(0,dates.indexOf(state.filters.start)):0;if(i>=dates.length-1)i=0;timelineSelect(i);elText('playButton',`Ⅱ ${tr('pause')}`);state.timelineTimer=setInterval(()=>{if(state.loading)return;i++;if(i>=dates.length){stopTimeline();return;}$('timelineRange').value=i;timelineSelect(i);},1800);}
async function renderCompanyQuick(){
 if(state.user?.role!=='company')return;
 const list=$('companyQuickCards');
 try{
  const result=await api('/api/areas');
  // A sign-out may finish before the request returns.
  if(state.user?.role!=='company')return;
  list.innerHTML=result.areas.length?result.areas.slice(0,4).map(a=>`<article class="area-card"><h3>${esc(a.name)}</h3><p>${esc(areaName(a.country))} · ${pretty(a.radius_km)} km</p><div class="area-metrics"><div><b>${pretty(a.detections)}</b><span>${esc(tr('radiusResults'))}</span></div><div><b>${pretty(a.max_frp,1)}</b><span>Max FRP (MW)</span></div></div></article>`).join(''):`<div class="empty">${esc(tr('noAreas'))}</div>`;
 }catch(err){list.textContent=err.message}
}
async function loadAreas(){const protectedEl=$('areasProtected');const gate=$('areasGate');gate.classList.toggle('hidden',!!state.user);protectedEl.classList.toggle('hidden',!state.user);if(!state.user)return;renderAreaCountryOptions();try{const r=await api('/api/areas');$('areaCards').innerHTML=r.areas.length?r.areas.map(a=>`<article class="area-card"><h3>${esc(a.name)}</h3><p>${esc(areaName(a.country))} · ${pretty(a.radius_km)} km · ${Number(a.lat).toFixed(3)}, ${Number(a.lon).toFixed(3)} ${a.category?'· '+esc(a.category):''}</p><div class="area-metrics"><div><b>${pretty(a.detections)}</b><span>${esc(tr('radiusResults'))}</span></div><div><b>${pretty(a.max_frp,1)}</b><span>Max FRP (MW)</span></div></div><div class="area-metrics"><span>${esc(tr('lastSeen'))}: ${esc(a.latest_detection||'—')}</span><button class="area-delete" data-delete="${Number(a.id)}">${esc(tr('delete'))}</button></div></article>`).join(''):`<div class="empty">${esc(tr('noAreas'))}</div>`;}catch(e){toast(e.message)}}
async function onSaveArea(e){e.preventDefault();if(!state.user){openAuth();return;}const form={name:$('areaName').value.trim(),country:$('areaCountry').value,lat:Number($('areaLat').value),lon:Number($('areaLon').value),radius_km:Number($('areaRadius').value),category:$('areaCategory').value.trim()};try{await api('/api/areas',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form)});$('areaForm').reset();$('areaRadius').value=50;toast(tr('saved'));loadAreas();renderCompanyQuick();}catch(err){toast(err.message||tr('saveError'))}}
async function onDeleteArea(id){try{await api('/api/areas/'+id,{method:'DELETE'});toast(tr('removed'));loadAreas();renderCompanyQuick();}catch(e){toast(e.message)}}
function openAuth(){const modal=$('authModal');modal.classList.remove('hidden');$('authEmail').focus();}
function closeAuth(){$('authModal').classList.add('hidden');$('authError').textContent='';}
function switchAuth(isRegister){state.authRegister=isRegister;$('showLogin').classList.toggle('active',!isRegister);$('showRegister').classList.toggle('active',isRegister);$('registerExtras').classList.toggle('hidden',!isRegister);elText('authHeading',tr(isRegister?'createAccount':'welcomeBack'));elText('authSubmit',tr(isRegister?'createAccount':'signIn'));$('authPassword').setAttribute('autocomplete',isRegister?'new-password':'current-password');$('authError').textContent='';}
async function handleAuth(e){e.preventDefault();const body={email:$('authEmail').value,password:$('authPassword').value};if(state.authRegister){body.full_name=$('authName').value;body.role=$('authRole').value;if(body.role==='company')body.company_name=$('authCompany').value;}try{const r=await api('/api/auth/'+(state.authRegister?'register':'login'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});state.user=r.account;closeAuth();renderAccountButton();renderNav();renderPageHeader();toast(tr(state.authRegister?'registered':'signedIn'));if(state.page==='areas')loadAreas();}catch(err){elText('authError',err.message)}}
async function handleAccount(){if(!state.user){openAuth();return;}if(!window.confirm(tr('logoutQuestion')))return;try{await api('/api/auth/logout',{method:'POST'});state.user=null;toast(tr('logoutDone'));renderAccountButton();if(state.page==='areas')loadAreas();renderNav();renderPageHeader();}catch(e){toast(e.message)}}
function bindEvents(){document.querySelectorAll('.language-toggle button').forEach(b=>b.addEventListener('click',()=>{state.lang=b.dataset.lang;applyTranslations();}));$('nav').addEventListener('click',e=>{const btn=e.target.closest('[data-page]');if(btn)navigate(btn.dataset.page);});document.body.addEventListener('click',e=>{const btn=e.target.closest('button[data-page]');if(btn&&btn.closest('#nav')===null)navigate(btn.dataset.page);const rm=e.target.closest('button[data-delete]');if(rm)onDeleteArea(Number(rm.dataset.delete));});
$('regionFilter').addEventListener('change',e=>{stopTimeline();state.filters.region=e.target.value;state.filters.country='';renderCountryOptions();state.prevGeoKey='';refresh()});
$('countryFilter').addEventListener('change',e=>{stopTimeline();state.filters.country=e.target.value;state.prevGeoKey='';refresh()});
for(const [el,key] of [['fromFilter','start'],['toFilter','end'],['instrumentFilter','instrument'],['confidenceFilter','confidence'],['daynightFilter','daynight']]){$(el).addEventListener('change',e=>{stopTimeline();state.filters[key]=e.target.value;if(state.filters.start&&state.filters.end&&state.filters.start>state.filters.end){toast(tr('invalidDates'));state.filters[key]=key==='start'?state.filters.end:state.filters.start;syncFilterInputs();return;}refresh();});}
$('clearFilters').addEventListener('click',()=>{stopTimeline();state.filters={region:'',country:'',start:'',end:'',instrument:'',confidence:'',daynight:''};state.prevGeoKey='';renderCountryOptions();syncFilterInputs();renderTimeline();refresh();});
$('heatButton').addEventListener('click',()=>{state.mapMode='heat';$('heatButton').classList.add('active');$('pointsButton').classList.remove('active');renderMapCells()});
$('pointsButton').addEventListener('click',()=>{state.mapMode='point';$('pointsButton').classList.add('active');$('heatButton').classList.remove('active');renderMapCells()});
$('playButton').addEventListener('click',playTimeline);$('timelineRange').addEventListener('input',e=>{stopTimeline();timelineSelect(e.target.value)});
$('exportButton').addEventListener('click',()=>{location.href='/api/observations.csv?'+urlParams()});
$('areasLoginButton').addEventListener('click',openAuth);$('accountButton').addEventListener('click',handleAccount);$('closeAuth').addEventListener('click',closeAuth);$('authModal').addEventListener('click',e=>{if(e.target.id==='authModal')closeAuth()});
$('showLogin').addEventListener('click',()=>switchAuth(false));$('showRegister').addEventListener('click',()=>switchAuth(true));$('authRole').addEventListener('change',e=>$('companyNameField').classList.toggle('hidden',e.target.value!=='company'));
$('authForm').addEventListener('submit',handleAuth);$('areaForm').addEventListener('submit',onSaveArea);$('menuButton').addEventListener('click',()=>$('sidebar').classList.toggle('open'));window.addEventListener('resize',()=>{state.map?.invalidateSize();Object.values(state.chartInstances).forEach(x=>x.resize());});}
async function boot(){bindEvents();applyTranslations();switchAuth(false);try{const [meta,geo,me]=await Promise.all([api('/api/meta'),fetch('/api/countries.geojson').then(r=>r.json()),api('/api/auth/me').catch(()=>null)]);state.meta=meta;state.geo=geo;state.user=me?.account||null;for(const key of ['fromFilter','toFilter']){$(key).min=meta.min_date;$(key).max=meta.max_date;}
renderRegionOptions();renderCountryOptions();renderAreaCountryOptions();renderAccountButton();renderNav();renderMetaText();renderTimeline();mountMap('overview');await refresh();setInterval(async()=>{if(document.visibilityState==='hidden')return;try{const latest=await api('/api/meta');if(latest.dataset?.imported_at_utc!==state.meta.dataset?.imported_at_utc){state.meta=latest;renderRegionOptions();renderCountryOptions();renderAreaCountryOptions();renderTimeline();renderMetaText();state.prevGeoKey='';await refresh();}}catch(e){console.warn('Dataset status check:',e.message)}},600000);}
catch(err){console.error(err);elText('loadIndicator',err.message||tr('error'));toast(err.message||tr('error'));}}
window.addEventListener('DOMContentLoaded',boot);
